import { readFileSync } from 'node:fs';
import { encode } from '../server/runtime';
import { normalizeMessage, type GmailMessage, type NormalizedMessage } from '../server/message';

/**
 * The reply-review workbook as test data (generated by scripts/reply-workbook-fixture.py).
 *
 * Each example is kept in separate fields. The classifier only ever receives the email —
 * and, in context-aware runs, the recipient context as its own trusted input. The expected
 * label, the rationale and the suggested action are never passed to it.
 *
 * Names, addresses and companies are fictional, and many unrelated scenarios share a domain,
 * so nothing here may be read as one person's inbox or as a working relationship.
 */
export type WorkbookRow = {
  id: string;
  /** yes = prompt reply, routine = "Not urgent reply", no = no email reply expected. */
  expected: 'yes' | 'routine' | 'no';
  importance: number;
  subject: string;
  email: string;
  why: string;
  action: string;
  category: string;
  recipientContext: string;
};

export const WORKBOOK_RECIPIENT = 'alex@northstar.example';
/** Fixed arrival time for every example: the workbook's research date. */
export const WORKBOOK_RECEIVED = Date.UTC(2026, 8, 30, 16, 0, 0);

export const workbookRows: WorkbookRow[] =
  (JSON.parse(readFileSync('tests/fixtures/reply-workbook.json', 'utf8')) as { rows: WorkbookRow[] }).rows;

/** Whether the workbook places the example in the "Needs a reply" tab. */
export const expectsReply = (row: WorkbookRow) => row.expected !== 'no';

/** The adapted email as Gmail would deliver it: headers, then a plain-text body. */
export function workbookMessage(row: WorkbookRow, extraHeaders: { name: string; value: string }[] = []): NormalizedMessage {
  const [head, ...rest] = row.email.replace(/\r\n/g, '\n').split('\n\n');
  const headers = head.split('\n').map((line) => {
    const at = line.indexOf(':');
    return { name: line.slice(0, at).trim(), value: line.slice(at + 1).trim() };
  });
  const raw: GmailMessage = {
    id: row.id, threadId: `thread-${row.id}`, snippet: '', internalDate: String(WORKBOOK_RECEIVED), labelIds: ['INBOX'],
    payload: { mimeType: 'text/plain', headers: [...headers, ...extraHeaders], body: { data: encode(rest.join('\n\n')) } },
  } as GmailMessage;
  return normalizeMessage(raw);
}

export type Score = { tp: number; fp: number; fn: number; tn: number; falsePositives: string[]; falseNegatives: string[] };

/** Precision and recall for "belongs in Needs a reply", with the IDs behind every miss. */
export function score(predicted: Map<string, boolean>, rows = workbookRows): Score {
  const result: Score = { tp: 0, fp: 0, fn: 0, tn: 0, falsePositives: [], falseNegatives: [] };
  for (const row of rows) {
    const want = expectsReply(row), got = predicted.get(row.id) === true;
    if (want && got) result.tp++;
    else if (!want && got) { result.fp++; result.falsePositives.push(row.id); }
    else if (want && !got) { result.fn++; result.falseNegatives.push(row.id); }
    else result.tn++;
  }
  return result;
}

export const precision = (s: Score) => s.tp / Math.max(1, s.tp + s.fp);
export const recall = (s: Score) => s.tp / Math.max(1, s.tp + s.fn);
